create table if not exists public.creator_protocol_reserved_powers (id uuid primary key default gen_random_uuid(), constitution_id uuid not null, organization_id uuid not null, power_key text not null, status text not null, version text not null, effective_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_amendments (id uuid primary key default gen_random_uuid(), constitution_id uuid not null, amendment_class text not null, title text not null, proposal_manifest_id uuid, status text not null default 'draft', policy_version text not null, idempotency_key text not null unique, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_decisions (id uuid primary key default gen_random_uuid(), amendment_id uuid, decision_type text not null, eligible_snapshot jsonb not null, result jsonb not null, status text not null, decided_at timestamptz, audit_event_id uuid, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_review_cases (id uuid primary key default gen_random_uuid(), challenged_decision_id uuid, filer_party_id uuid, status text not null default 'filed', requested_relief jsonb not null default '[]'::jsonb, confidentiality text not null default 'public', policy_version text not null, created_at timestamptz not null default now());
alter table public.creator_protocol_reserved_powers enable row level security; alter table public.creator_protocol_amendments enable row level security; alter table public.creator_protocol_decisions enable row level security; alter table public.creator_protocol_review_cases enable row level security;
